def fewest_end_lots(lots, x):
    keep = sum(lots) - x
    if keep < 0:
        return -1
    best = 0 if keep == 0 else -1
    left = total = 0
    for right, v in enumerate(lots):
        total += v
        while total > keep:
            total -= lots[left]
            left += 1
        if total == keep:
            best = max(best, right - left + 1)
    return -1 if best < 0 else len(lots) - best

