def fewest_end_lots(lots, x):
    keep = sum(lots) - x
    if keep < 0:
        return -1
    best = 0 if keep == 0 else -1
    left = total = 0
    for right, v in enumerate(lots):
        total += v
        while total > keep:
            total -= lots[left]
            left += 1
        if total == keep:
            best = max(best, right - left + 1)
    return best

def fewest_end_lots(lots, x):
    n = len(lots)
    best = -1
    front = 0
    for a in range(n + 1):
        if a:
            front += lots[a - 1]
        if front > x:
            break
        back = 0
        for b in range(n - a + 1):
            if front + back == x:
                if best < 0 or a + b < best:
                    best = a + b
                break
            if b < n - a:
                back += lots[n - 1 - b]
    return best
